// Simple top‑down canvas game – Solar Flare Escape
// Canvas with id="game" must exist in the host HTML.
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth;
  const height = canvas.height = canvas.clientHeight;

  // ---- Helpers ---------------------------------------------------
  const rand = (min, max) => Math.random() * (max - min) + min;
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);

  // ---- Ship ------------------------------------------------------
  const ship = {
    x: width / 2,
    y: height / 2,
    angle: 0,
    vx: 0,
    vy: 0,
    radius: 10,
    thrusting: false,
  };
  const TURN_SPEED = 0.07; // rad per frame
  const THRUST = 0.1;
  const FRICTION = 0.99;

  // ---- Asteroids -------------------------------------------------
  const asteroids = [];
  const ASTEROID_MIN_SPEED = 0.5;
  const ASTEROID_MAX_SPEED = 2.0;
  const ASTEROID_MIN_SIZE = 15;
  const ASTEROID_MAX_SIZE = 40;
  const SPAWN_INTERVAL = 1500; // ms

  const spawnAsteroid = () => {
    const size = rand(ASTEROID_MIN_SIZE, ASTEROID_MAX_SIZE);
    // spawn at random edge
    const edge = Math.floor(rand(0, 4));
    let x, y, vx, vy;
    if (edge === 0) { // top
      x = rand(0, width); y = -size;
    } else if (edge === 1) { // right
      x = width + size; y = rand(0, height);
    } else if (edge === 2) { // bottom
      x = rand(0, width); y = height + size;
    } else { // left
      x = -size; y = rand(0, height);
    }
    // direction toward centre with random variance
    const angle = Math.atan2(height / 2 - y, width / 2 - x) + rand(-0.5, 0.5);
    const speed = rand(ASTEROID_MIN_SPEED, ASTEROID_MAX_SPEED);
    vx = Math.cos(angle) * speed;
    vy = Math.sin(angle) * speed;
    asteroids.push({ x, y, vx, vy, radius: size });
  };

  // ---- Input ------------------------------------------------------
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.code] = true; });
  window.addEventListener('keyup', e => { keys[e.code] = false; });

  // ---- Game Loop -------------------------------------------------
  let lastSpawn = 0;
  let gameOver = false;

  const update = delta => {
    if (gameOver) return;
    // Ship control
    if (keys['ArrowLeft']) ship.angle -= TURN_SPEED;
    if (keys['ArrowRight']) ship.angle += TURN_SPEED;
    if (keys['ArrowUp']) {
      ship.vx += Math.cos(ship.angle) * THRUST;
      ship.vy += Math.sin(ship.angle) * THRUST;
      ship.thrusting = true;
    } else {
      ship.thrusting = false;
    }
    // Apply friction
    ship.vx *= FRICTION;
    ship.vy *= FRICTION;
    // Move ship
    ship.x += ship.vx;
    ship.y += ship.vy;
    // Wrap around edges
    if (ship.x < 0) ship.x += width;
    if (ship.x > width) ship.x -= width;
    if (ship.y < 0) ship.y += height;
    if (ship.y > height) ship.y -= height;

    // Asteroid movement and spawn
    const now = performance.now();
    if (now - lastSpawn > SPAWN_INTERVAL) {
      spawnAsteroid();
      lastSpawn = now;
    }
    asteroids.forEach(a => {
      a.x += a.vx;
      a.y += a.vy;
      // wrap
      if (a.x < -a.radius) a.x = width + a.radius;
      if (a.x > width + a.radius) a.x = -a.radius;
      if (a.y < -a.radius) a.y = height + a.radius;
      if (a.y > height + a.radius) a.y = -a.radius;
    });

    // Collision detection
    for (const a of asteroids) {
      if (dist(ship, a) < ship.radius + a.radius) {
        gameOver = true;
        break;
      }
    }
  };

  const draw = () => {
    ctx.clearRect(0, 0, width, height);
    // Ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(12, 0);
    ctx.lineTo(-8, -8);
    ctx.lineTo(-6, 0);
    ctx.lineTo(-8, 8);
    ctx.closePath();
    ctx.fillStyle = ship.thrusting ? 'orange' : 'white';
    ctx.fill();
    ctx.restore();
    // Asteroids
    ctx.fillStyle = 'gray';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    });
    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = 'red';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  };

  let lastTime = 0;
  const loop = timestamp => {
    const delta = timestamp - lastTime;
    lastTime = timestamp;
    update(delta);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
})();
